"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["77615"],{15343(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.termo_consentimento.forma_aceite_invalida","status":422,"titulo":"Forma de aceite do termo n\xe3o \xe9 um dos c\xf3digos aceitos"},"descricao":{"codigo":"uniplus.configuracao.termo_consentimento.forma_aceite_invalida","requisitos":["UNI-REQ-0086"],"oQueAconteceu":["Cada termo tem uma forma de aceite, que s\xf3 pode ser uma destas tr\xeas (UNI-REQ-0086): `A_DEFINIR`, `REGISTRO_DIGITAL_SEM_LOG_IP` ou `REGISTRO_DIGITAL_COM_LOG_IP`. O campo `formaAceiteRascunho`, no cadastro (`POST /api/configuracao/admin/termos-consentimento`) ou na edi\xe7\xe3o do rascunho (`PUT /api/configuracao/admin/termos-consentimento/{id}/rascunho`), trouxe outro valor. A compara\xe7\xe3o desconsidera os espa\xe7os nas pontas, mas diferencia mai\xfasculas de min\xfasculas, e nomes por extenso ou n\xfameros n\xe3o valem.","A recusa vem na lista `errors` da resposta, com `field` igual a `formaAceiteRascunho`, e a mensagem lista as formas aceitas. As demais recusas do corpo v\xeam na mesma resposta, e nada \xe9 gravado. Na edi\xe7\xe3o, o `id` do corpo diferente do da rota \xe9 recusado com 400 antes das demais confer\xeancias, e em seguida o corpo \xe9 conferido, antes da busca do termo: um `{id}` que n\xe3o existe s\xf3 responde como n\xe3o encontrado quando o corpo \xe9 v\xe1lido."],"comoResolver":["Envie uma das tr\xeas formas, exatamente como escritas acima, ou omita o campo: sem forma de aceite informada, o rascunho fica em `A_DEFINIR`, e na edi\xe7\xe3o a omiss\xe3o tamb\xe9m devolve a forma a `A_DEFINIR`. A publica\xe7\xe3o de um processo recusa o termo exigido que ainda esteja em `A_DEFINIR`."],"ondeAparece":["Cadastro de um termo de consentimento","Edi\xe7\xe3o do rascunho de um termo de consentimento"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Termo consentimento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);